import React from 'react';
import { Link } from 'react-router-dom'; // Import Link from react-router-dom
import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
function Kungfu(){
    const navigate = useNavigate();
    const { ref, inView } = useInView();
    const [isVideoOpen, setIsVideoOpen] = useState(false);
    return(
        <>
        <p
        className="underline text-base sm:text-lg md:text-xl lg:text-l cursor-pointer pl-5"
        onClick={() => navigate(-1)}
      >
        Go Back
      </p>

      {/* Heading Section */}
      <div className="flex flex-col items-center justify-center mt-10">
        <h2 className="text-3xl font-bold text-black text-center">A Walk in the Past</h2>
      </div>

      {/* Video Placeholder with Cover Image */}
      <div className="flex justify-center items-center w-full mt-10 px-4">
        <div
          className="relative w-full max-w-4xl h-[250px] sm:h-[350px] md:h-[450px] lg:h-[500px] bg-cover bg-center cursor-pointer flex items-center justify-center"
          style={{ backgroundImage: "url('/kalpana.avif')" }}
          onClick={() => setIsVideoOpen(true)}
        >

        </div>
      </div>

      {/* Video Modal */}
      {isVideoOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-80 flex items-center justify-center z-50 p-4">
          <div className="relative w-full max-w-6xl bg-black p-4 rounded-lg shadow-lg">
            {/* Close Button */}
            <button
              className="absolute top-2 right-2 text-white text-2xl"
              onClick={() => setIsVideoOpen(false)}
            >
              ✖
            </button>

            {/* Video Player */}
            <video
              controls
              autoPlay
              className="w-full h-auto max-h-[80vh] rounded-lg"
            >
              <source src="/kalpana.mp4" type="video/mp4" />
              Your browser does not support the video tag.
            </video>
          </div>
        </div>
      )}



     <div className="flex flex-wrap justify-between w-full max-w-3xl items-start gap-4">
        <ul className="space-y-1">
            <li className="text-lg font-semibold">CONTACT</li>
            <li><a href="mailto:sanskritichauhan1234@gmail.com" className="hover:underline">sanskritichauhan1234@gmail.com</a></li>
            <li><a href="tel:+919867067656" className="hover:underline">+91 9867067656</a></li>
        </ul>

        <nav>
            <ul className="flex flex-col items-center space-y-1">
                <Link to="/" className="text-lg hover:underline">HOME</Link>
                <Link to="/about" className="text-lg hover:underline">ABOUT</Link>
                <Link to="/portfolio" className="text-lg hover:underline">PORTFOLIO</Link>
                <Link to="/photography" className="text-lg hover:underline">PHOTOGRAPHY</Link>
            </ul>
        </nav>
    </div>

    {/* Name Display - Animated */}
    <motion.div 
        ref={ref} // Attach the ref here for visibility detection
        className=" text-center"
        initial={{ opacity: 0, y: 50 }}
        animate={inView ? { opacity: 1, y: 0 } : {}}
        transition={{ duration: 0.8, ease: "easeOut" }}
    >
        <span className="mt-36 font-extrabold text-4xl lg:text-5xl whitespace-nowrap block">SANSKRITI CHAUHAN</span>
    </motion.div>
        </>
    )
};

export default Kungfu;
